import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();

  // Colors
  const colors = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  // Constants
  const CARD_WIDTH = 1.6;
  const CARD_HEIGHT = 1.0;
  const CARD_PITCH = 1.85;
  const FRAME_THICKNESS = 0.025;
  const STRIP_ROTATION_DEG = -18;
  const STRIP_ROTATION_RAD = STRIP_ROTATION_DEG * Math.PI / 180;
  const PARALLAX_INTENSITY = 0.5;
  const SNAP_DURATION = 0.9;
  const SNAP_EASING = 'cubic-bezier(0.165,0.84,0.44,1)';

  const CARD_CAPTIONS = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];

  // Load texture
  const textureMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');

  // Create filmstrip group
  const filmstrip = new THREE.Group();
  filmstrip.rotation.y = STRIP_ROTATION_RAD;
  root.add(filmstrip);

  // Create 5 cards
  const cards = [];
  for (let i = 0; i < 5; i++) {
    const card = createCard({
      width: CARD_WIDTH,
      height: CARD_HEIGHT,
      frameThickness: FRAME_THICKNESS,
      textureMap: textureMap,
      colors: colors,
      ctx: ctx,
      caption: CARD_CAPTIONS[i],
    });

    card.position.x = (i - 2) * CARD_PITCH;
    filmstrip.add(card);
    cards.push(card);
  }

  // Create headline text
  const headlineText = ctx.fontAtlas('The collection', {
    font: 'Lora',
    weight: 600,
    height: 0.34,
    color: colors.paper,
  });
  headlineText.position.set(-2.6, 1.5, 0.1);
  root.add(headlineText);

  // Create body text
  const bodyText = ctx.fontAtlas('Five calibres. One discipline.', {
    font: 'JetBrains Mono',
    weight: 400,
    height: 0.2,
    color: colors.paper,
  });
  bodyText.position.set(-2.6, -1.5, 0.1);
  root.add(bodyText);

  // State
  let filmstripX = 0;
  let currentCardIndex = 2;
  let isSnapping = false;

  function getCardIndexFromPosition(x) {
    const index = -x / CARD_PITCH + 2;
    return Math.max(0, Math.min(4, Math.round(index)));
  }

  function updateCardStates() {
    cards.forEach((card, i) => {
      const isFocused = i === currentCardIndex;

      // Scale
      gsap.to(card.scale, {
        x: isFocused ? 1.0 : 0.92,
        y: isFocused ? 1.0 : 0.92,
        duration: 0.2,
        overwrite: 'auto',
      });

      // Opacity
      const targetOpacity = isFocused ? 1.0 : 0.55;
      gsap.to(card.userData.mainMaterial, {
        opacity: targetOpacity,
        duration: 0.2,
        overwrite: 'auto',
      });
      gsap.to(card.userData.edgeMaterial, {
        opacity: targetOpacity,
        duration: 0.2,
        overwrite: 'auto',
      });

      // Counter-rotation
      const targetRotY = isFocused ? -STRIP_ROTATION_RAD : 0;
      gsap.to(card.rotation, {
        y: targetRotY,
        duration: 0.2,
        overwrite: 'auto',
      });

      // Emissive bar visibility
      if (card.userData.emissiveBar) {
        card.userData.emissiveBar.visible = isFocused;
      }
    });
  }

  function snapToCard() {
    if (isSnapping) return;

    const targetX = -(currentCardIndex - 2) * CARD_PITCH;

    isSnapping = true;
    gsap.to(filmstrip.position, {
      x: targetX,
      duration: SNAP_DURATION,
      ease: SNAP_EASING,
      onUpdate: () => {
        filmstripX = filmstrip.position.x;
      },
      onComplete: () => {
        filmstripX = targetX;
        isSnapping = false;
      },
    });
  }

  // Apply parallax-scroll primitive
  ctx.primitives['parallax-scroll'](filmstrip, {
    intensity: PARALLAX_INTENSITY,
  });

  // Event handlers
  root.userData.handlers = {
    onScroll: (delta) => {
      if (isSnapping) return;
      filmstripX += delta * PARALLAX_INTENSITY;
      filmstrip.position.x = filmstripX;

      const newIndex = getCardIndexFromPosition(filmstripX);
      if (newIndex !== currentCardIndex) {
        currentCardIndex = newIndex;
        updateCardStates();
      }
    },
    onScrollEnd: () => {
      snapToCard();
    },
  };

  // Cleanup
  root.userData.cleanup = () => {
    gsap.killTweensOf([
      filmstrip.position,
      ...cards.map(c => c.scale),
      ...cards.map(c => c.rotation),
      ...cards.map(c => c.userData.mainMaterial),
      ...cards.map(c => c.userData.edgeMaterial),
    ]);

    // Dispose resources
    [filmstrip, headlineText, bodyText].forEach(obj => {
      obj.traverse((node) => {
        if (node.geometry) node.geometry.dispose();
        if (node.material) {
          if (Array.isArray(node.material)) {
            node.material.forEach(m => m.dispose());
          } else {
            node.material.dispose();
          }
        }
      });
    });
  };

  // Initialize
  updateCardStates();

  return root;
}

function createCard(options) {
  const {
    width,
    height,
    frameThickness,
    textureMap,
    colors,
    ctx,
    caption,
  } = options;

  const cardGroup = new THREE.Group();

  // Main card plane with PBR material
  const planeGeo = new THREE.PlaneGeometry(width, height);
  const planeMat = new THREE.MeshStandardMaterial({
    map: textureMap,
    roughness: 0.55,
    metalness: 0.2,
    clearcoat: 0.15,
    transparent: true,
    opacity: 1.0,
  });
  const planeMesh = new THREE.Mesh(planeGeo, planeMat);
  planeMesh.position.z = 0;
  cardGroup.add(planeMesh);
  cardGroup.userData.mainMaterial = planeMat;

  // Frame bevel using edges geometry
  const edgesGeo = new THREE.EdgesGeometry(planeGeo);
  const edgesMat = new THREE.LineBasicMaterial({
    color: colors.ink,
    linewidth: frameThickness * 100,
    transparent: true,
    opacity: 1.0,
  });
  const edgesMesh = new THREE.LineSegments(edgesGeo, edgesMat);
  edgesMesh.position.z = 0.001;
  cardGroup.add(edgesMesh);
  cardGroup.userData.edgeMaterial = edgesMat;

  // Emissive underline bar (for focused card)
  const barGeo = new THREE.PlaneGeometry(width, 0.035);
  const barMat = new THREE.MeshBasicMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.3,
  });
  const barMesh = new THREE.Mesh(barGeo, barMat);
  barMesh.position.set(0, -height / 2 - 0.25, 0.01);
  barMesh.visible = false;
  cardGroup.add(barMesh);
  cardGroup.userData.emissiveBar = barMesh;

  // Caption text
  const captionMesh = ctx.fontAtlas(caption, {
    font: 'JetBrains Mono',
    weight: 700,
    height: 0.09,
    color: colors.paper,
  });
  captionMesh.position.set(0, -height / 2 - 0.5, 0.02);
  cardGroup.add(captionMesh);

  return cardGroup;
}
